def profiles():
    result = []
    for line in PROFILE_SOURCE.strip().splitlines():
        slug, title, entity, group, date, metrics = line.split("|")
        result.append({"id": slug, "title": title, "entity": entity,
                       "group": group, "date": date, "metrics": metrics.split(",")})
    return result
